#include <stdio.h>
#include <string.h>
#include <ctype.h>

#define OUT_BUF_SIZE 1024

int main(int argc, char **argv) {
    if (argc < 3) {
        puts("USAGE");
        return 0;
    }
    const char *mode = argv[1];
    const char *input = argv[2];
    char out[OUT_BUF_SIZE];
    size_t out_len = 0;

    if (strcmp(mode, "to_camel") == 0) {
        int capitalize_next = 0;
        for (size_t i = 0; input[i] != '\0'; ++i) {
            char c = input[i];
            if (c == '_') {
                capitalize_next = 1;
                continue;
            }
            if (out_len + 1 >= OUT_BUF_SIZE) break;
            if (capitalize_next) {
                out[out_len++] = (char)toupper((unsigned char)c);
                capitalize_next = 0;
            } else {
                out[out_len++] = (char)tolower((unsigned char)c);
            }
        }
    } else if (strcmp(mode, "to_snake") == 0) {
        for (size_t i = 0; input[i] != '\0'; ++i) {
            char c = input[i];
            if (isupper((unsigned char)c)) {
                if (out_len > 0) {
                    if (out_len + 1 >= OUT_BUF_SIZE) break;
                    out[out_len++] = '_';
                }
                c = (char)tolower((unsigned char)c);
            }
            if (out_len + 1 >= OUT_BUF_SIZE) break;
            out[out_len++] = c;
        }
    } else {
        puts("INVALID_MODE");
        return 0;
    }
    out[out_len] = '\0';
    puts(out);
    return 0;
}
